    async def stream_events(
        self,
        project_id: str,
        run_id: str,
        *,
        after: typing.Optional[str] = None,
        last_event_id: typing.Optional[str] = None,
        request_options: typing.Optional[RequestOptions] = None,
    ) -> typing.AsyncIterator[RunEvent]:
        """
        Replay and stream durable run events; resume using after or Last-Event-ID.

        A terminal run event ends the stream. Idle streams may also close: callers
        can resume from their last delivered event without restarting the run.

        Parameters
        ----------
        project_id : str

        run_id : str

        after : typing.Optional[str]

        last_event_id : typing.Optional[str]

        request_options : typing.Optional[RequestOptions]
            Request-specific configuration.

        Yields
        ------
        typing.AsyncIterator[RunEvent]
            Successful Response

        Examples
        --------
        import asyncio

        from sikaru_sdk import AsyncSikaruApi

        client = AsyncSikaruApi(
            channel_credential="YOUR_CHANNEL_CREDENTIAL",
            api_key="YOUR_API_KEY",
        )


        async def main() -> None:
            response = client.runs.stream_events(
                project_id="project_id",
                run_id="run_id",
            )
            async for chunk in response:
                yield chunk


        asyncio.run(main())
        """
        async with self._raw_client.stream_events(
            project_id, run_id, after=after, last_event_id=last_event_id, request_options=request_options
        ) as r:
            async for _chunk in r.data:
                yield _chunk

